export type RunState = "running" | "completed" | "failed" | "unknown" | "recorded";

export function StatusIndicator({ state }: { state: RunState }) {
  return state === "running" ? <span className="loading-spinner" aria-label="运行中" />
      : <svg className="run-status-icon" viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
        {state === "completed" ? <path d="m3.5 8 3 3 6-7" />
          : state === "failed" ? <path d="m4.5 4.5 7 7m0-7-7 7" />
            : state === "unknown" ? <><circle cx="8" cy="8" r="5.5" /><path d="M6.5 6a1.5 1.5 0 0 1 3 .3c0 1.2-1.5 1.2-1.5 2.4m0 2h.01" /></>
              : <><circle cx="8" cy="8" r="5.5" /><path d="M8 4.5V8l2.5 1.5" /></>}
      </svg>;
}

/** Only display states supported by the loaded execution records. */
export default function RunStatus({ label, state = "recorded" }: { label: string; state?: RunState }) {
  return <span className="run-status" data-state={state}>
    <StatusIndicator state={state} />
    <span className="event-label">{label}</span>
  </span>;
}


import type { WorkerRun } from "../../ConversationRuntime";
import type { Outgoing } from "../../timeline";
import UserMessage from "./UserMessage";
import AssistantMessage from "./AssistantMessage";
import EventGroup from "./EventGroup";
import { eventKey, type DisplayItem, type EventViewMemory, type HistoryProps, type Quest } from "./eventModel";

export interface MessageListProps extends HistoryProps {
  items: DisplayItem[];
  identity: string;
  quests: Quest[];
  workerRuns: WorkerRun[];
  memory: EventViewMemory;
  native: boolean;
  canRetry: boolean;
  onRetry: (item: Outgoing) => void;
  onQuest: (id: string) => void;
  onOpenFile?: (path: string) => void;
  onInspect: () => void;
}

/** Keep persisted ordering and stable keys while components own their individual rendering. */
export default function MessageList({ items, identity, quests, workerRuns, memory, native, canRetry, onRetry, onQuest, onOpenFile, onInspect, ...history }: MessageListProps) {
  return <div className="conversation-list">{items.map((item) => {
    if (item.type === "group") return <EventGroup key={`${identity}|${eventKey(item.events[0])}`} item={item} quests={quests} runs={workerRuns} memory={memory}
      onQuest={onQuest} onOpenFile={onOpenFile} onInspect={onInspect} {...history} />;
    if (item.type === "outgoing") return <UserMessage key={`outgoing:${item.value.requestId}`} outgoing={item.value} native={native} onInspect={onInspect} canRetry={canRetry} onRetry={onRetry} />;
    return item.value.role === "user" ? <UserMessage key={item.value.id} message={item.value} native={native} onInspect={onInspect} />
      : <AssistantMessage key={item.value.id} message={item.value} native={native} onInspect={onInspect} />;
  })}</div>;
}


import AnimatedDetails from "../AnimatedDetails";
import { Chevron } from "./conversation/Icons";

export interface TurnDiffFile {
  path: string;
  receiptId: string;
  scrollKey: string;
  added?: number;
  removed?: number;
}

export interface TurnDiffProps {
  files: TurnDiffFile[];
  groupKey: string;
  initialExpanded: boolean;
  onExpandedChange: (expanded: boolean) => void;
  onInspect: () => void;
  onOpenFile?: (path: string) => void;
  onOpenHistory?: (receiptId: string, path: string) => void;
}

/** A file summary is derived only from successful live receipts in this activity group. */
export default function TurnDiff({ files, groupKey, initialExpanded, onExpandedChange, onInspect, onOpenFile, onOpenHistory }: TurnDiffProps) {
  if (!files.length) return null;
  const row = (file: TurnDiffFile) => <button type="button" className="activity-file-row turn-diff-file" key={file.path} data-scroll-key={file.scrollKey} title={file.path} disabled={!onOpenFile}
    onClick={() => { onInspect(); onOpenFile?.(file.path); }}>
    <svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.3" aria-hidden="true"><path d="M4 2h5l3 3v9H4V2Zm5 0v3h3" /></svg>
    <span className="turn-diff-path">{file.path}</span>
    {typeof file.added === "number" && typeof file.removed === "number" && <span className="turn-diff-stats" title="此文件已加载回执的增删数"><span className="file-added">+{file.added.toLocaleString()}</span><span className="file-removed">−{file.removed.toLocaleString()}</span></span>}
    <span className="activity-file-action">预览</span>
  </button>;
  return <section className="turn-diff activity-group-files" aria-label="记录的文件变更">
    <p className="activity-group-files-label sr-only">本组记录的文件</p>
    <header className="turn-diff-header"><span className="turn-diff-title">已编辑 {files.length} 个文件</span>
      {onOpenHistory && <div className="turn-diff-actions"><button type="button" onClick={() => { onInspect(); onOpenHistory(files[0].receiptId, files[0].path); }}>查看变更</button></div>}
    </header>
    <div className="turn-diff-files">{files.slice(0, 3).map(row)}</div>
    {files.length > 3 && <AnimatedDetails className="activity-more-files turn-diff-more" scrollKey={`group-files:${groupKey}`} initialExpanded={initialExpanded}
      onExpandedChange={onExpandedChange} onInspect={onInspect} summary={<><span>再显示 {files.length - 3} 个文件</span><Chevron /></>}>
      <div className="activity-more-files-body">{files.slice(3).map(row)}</div>
    </AnimatedDetails>}
  </section>;
}


import { useLayoutEffect, useState } from "react";
import AnimatedDetails from "../../AnimatedDetails";
import type { WorkerRun } from "../../ConversationRuntime";
import type { TimelineEvent } from "../../timeline";
import { relativeFilePath } from "../../workspaceFiles";
import TurnDiff from "../TurnDiff";
import ToolItem from "./ToolItem";
import RunStatus from "./RunStatus";
import { Chevron } from "./Icons";
import { activitySummary, eventKey, eventView, text, workerIdentity, type DisplayItem, type EventViewMemory, type HistoryProps, type Quest, type Row } from "./eventModel";

export default function EventGroup({ item, quests, runs, memory, onQuest, onOpenFile, onInspect, onOpenHistory, historyStats, connection, onHistoryLoaded }: { item: Extract<DisplayItem, { type: "group" }>; quests: Quest[]; runs: WorkerRun[]; memory: EventViewMemory; onQuest: (id: string) => void; onOpenFile?: (path: string) => void; onInspect: () => void } & HistoryProps) {
  const [expanded, setExpanded] = useState(() => item.events.some((event) => eventView(memory, event).groupExpanded));
  const [filesExpanded, setFilesExpanded] = useState(() => item.events.some((event) => eventView(memory, event).groupFilesExpanded));
  // Members inherit the current group state, so splits and prepended group roots restore it.
  useLayoutEffect(() => {
    for (const event of item.events) {
      eventView(memory, event).groupExpanded = expanded;
      eventView(memory, event).groupFilesExpanded = filesExpanded;
    }
  }, [item.events, memory, expanded, filesExpanded]);
  const summary = activitySummary(item.events, runs);
  const origins = [...new Set(item.events.map((event) => workerIdentity(event, runs)).filter(Boolean))];
  const hasMock = item.events.some((event) => event.execution_mode === "mock");
  const hasFailure = item.events.some((event) => /failed/.test(event.status || "") || typeof (event.detail as Row | undefined)?.exit_code === "number" && Number((event.detail as Row).exit_code) !== 0);
  const hasUnknown = item.events.some((event) => /unknown|uncertain/.test(event.status || ""));
  const recordedFiles = new Map<string, TimelineEvent>();
  for (const event of item.events) {
    const detail = event.detail && typeof event.detail === "object" ? event.detail as Row : {};
