  "storage" | "connections" | "maintenance" | "memory" | "triggers";

export interface SettingItem {
  id: SettingId;
  label: string;
  description: string;
  accessibleLabel?: string;
  keywords?: string;
}
interface SettingGroup { label: string; items: SettingItem[] }

