type RecordValue = Record<string, unknown>;

const transitions: Record<string, string[]> = {
  proposed: ["awaiting_approval", "rejected", "cancelled"],
  awaiting_approval: ["rejected", "cancelled"],
  approved: ["paused", "cancelled"], queued: ["paused", "cancelled"],
  running: ["blocked", "paused", "needs_input", "failed", "cancelled"],
  blocked: ["cancelled", "failed"], paused: ["cancelled"], needs_input: ["cancelled"],
  reviewing: ["failed"],
};

/** Execution and completion transitions belong to the trusted Core runtime. */
export const userQuestTransitions = (status: string): readonly string[] => transitions[status] || [];

const record = (value: unknown): RecordValue => {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new Error("团队合约不完整，请刷新团队记录。");
  return value as RecordValue;
};
const strings = (value: unknown): string[] => {
  if (!Array.isArray(value) || value.some((item) => typeof item !== "string")) throw new Error("团队合约缺少有效的角色或工具范围。");
  return value;
};
const integer = (value: unknown, minimum: number, maximum: number): number => {
  if (typeof value !== "number" || !Number.isSafeInteger(value) || value < minimum || value > maximum) throw new Error("团队预算或执行上限不完整。");
  return value;
};
const requiredText = (value: unknown): string => {
  if (typeof value !== "string" || !value.trim()) throw new Error("团队角色合约不完整。");
  return value;
};

/** Convert a recorded contract to the existing TeamWire without inventing authority. */
export function teamReassignmentProposal(value: unknown, strategy: string) {
  const body = record(value);
  if (!Array.isArray(body.roles) || !body.roles.length) throw new Error("请选择包含完整角色合约的团队记录。");
  if (!["single_model", "greedy", "coverage", "complementarity"].includes(strategy)) throw new Error("请选择团队选型策略。");
  const roles = body.roles.map((value) => {
    const role = record(value);
    const input = integer(role.input_tokens, 0, 1000000), output = integer(role.output_tokens, 1, 1000000);
    if (role.execution_token_budget != null && role.execution_token_budget !== input + output) {
      throw new Error("当前团队的累计 Token 分配无法通过此接口完整保留，请在长期对话中请求重新分配。");
    }
    const capabilities = record(role.required_capabilities);
    const requiredCapabilities = Object.entries(capabilities).map(([name, minimum]) => {
      if (typeof minimum !== "number" || !Number.isFinite(minimum) || minimum < 0 || minimum > 100) throw new Error("团队能力要求无效。");
      return { name, minimum };
    });
    if (typeof role.dynamic !== "boolean") throw new Error("团队角色来源未记录。");
    const schema = record(role.output_schema);
    return {
      id: requiredText(role.id), task_node_key: requiredText(role.task_node_key),
      required_capabilities: requiredCapabilities, tools: strings(role.tools),
      input_tokens: input, output_tokens: output,
      max_steps: integer(role.max_steps, 1, 32), max_tool_calls: integer(role.max_tool_calls, 0, 64),
      max_duration_seconds: integer(role.max_duration_seconds, 1, 3600), depth: integer(role.depth, 0, 8),
      dynamic: role.dynamic, responsibility: requiredText(role.responsibility),
      input_contract: strings(role.input_contract), output_schema_json: JSON.stringify(schema),
      acceptance_criteria: strings(role.acceptance_criteria),
    };
  });
  const limits = record(body.limits);
  if (limits.currency !== null && (typeof limits.currency !== "string" || !/^[A-Z]{3}$/.test(limits.currency))) throw new Error("团队预算币种未记录。");
  const wireLimits = {
    max_members: integer(limits.max_members, 1, 16), max_depth: integer(limits.max_depth, 0, 8),
    max_concurrency: integer(limits.max_concurrency, 1, 16), max_total_tokens: integer(limits.max_total_tokens, 1, 16000000),
    max_total_tool_calls: integer(limits.max_total_tool_calls, 0, 1024),
    max_cost_microunits: limits.max_cost_microunits === null ? null : integer(limits.max_cost_microunits, 0, Number.MAX_SAFE_INTEGER),
    currency: limits.currency, allowed_tools: strings(limits.allowed_tools),
  };
  return { roles, limits: wireLimits, strategy };
}

import test from "node:test";
import assert from "node:assert/strict";
import { teamReassignmentProposal, userQuestTransitions } from "../src/questControls.ts";

const schema = { type: "object", properties: { result: { type: "string" } }, required: ["result"], additionalProperties: false };
const team = {
  roles: [{ id: "coding", task_node_key: "implement", required_capabilities: { coding: 70 }, tools: ["file_read"], input_tokens: 100, output_tokens: 200, execution_token_budget: 300, max_steps: 4, max_tool_calls: 2, max_duration_seconds: 60, depth: 0, dynamic: false, responsibility: "Implement assigned work", input_contract: ["approved node"], output_schema: schema, acceptance_criteria: ["valid evidence"] }],
  limits: { max_members: 1, max_depth: 0, max_concurrency: 1, max_total_tokens: 300, max_total_tool_calls: 2, max_cost_microunits: null, currency: null, allowed_tools: ["file_read"] },
};
test("team reassignment preserves the recorded contracts, tool scopes and limits in the existing wire format", () => {
  const wire = teamReassignmentProposal(team, "greedy");
  assert.deepEqual(wire.limits, team.limits);
  assert.deepEqual(wire.roles[0].required_capabilities, [{ name: "coding", minimum: 70 }]);
  assert.deepEqual(JSON.parse(wire.roles[0].output_schema_json), schema);
  assert.deepEqual(wire.roles[0].tools, ["file_read"]);
  assert.equal(wire.roles[0].task_node_key, "implement");
  assert.equal("execution_token_budget" in wire.roles[0], false);
  assert.deepEqual(team.roles[0].required_capabilities, { coding: 70 });
});
test("an unrepresentable cumulative allocation or incomplete role contract cannot silently change a team", () => {
  assert.throws(() => teamReassignmentProposal({ ...team, roles: [{ ...team.roles[0], execution_token_budget: 900 }] }, "greedy"), /累计 Token/);
  assert.throws(() => teamReassignmentProposal({ ...team, roles: [{ ...team.roles[0], output_schema: null }] }, "greedy"), /合约不完整/);
});
test("task controls never offer execution or completion transitions reserved to the trusted runtime", () => {
  for (const state of ["proposed", "awaiting_approval", "approved", "queued", "running", "blocked", "paused", "needs_input", "reviewing", "completed", "failed", "cancelled"]) {
    assert.equal(userQuestTransitions(state).some(target => ["approved", "queued", "running", "reviewing", "completed"].includes(target)), false);
  }
  assert.deepEqual(userQuestTransitions("running"), ["blocked", "paused", "needs_input", "failed", "cancelled"]);
  assert.deepEqual(userQuestTransitions("completed"), []);
});

import { useCallback, useEffect } from "react";
import { ApiError, request } from "../api";
import { errorMessage } from "../logic";
import { Row, Quest, EMPTY, text, rows } from "../workspaceTypes";
import type { WorkspaceState } from "./useWorkspaceState";
import useConversationFeed from "./useConversationFeed";

export default function useWorkspaceInspector(workspace: WorkspaceState & ReturnType<typeof useConversationFeed>) {
  const { connection, maintenanceSubmitting, view, refreshing, setRefreshing, quests, setQuests, selectedId, panel, setPanel, setPanelContext, setQuestPlan, planRefresh, setPlanRefresh, planContext, setPlanContext, setGrants, setGrantContext, setGrantScope, setWorkspaceRoot, setActionError, actionBusy, setActionBusy, actionNotice, setActionNotice, memorySearch, memoryCursor, setMemoryCursor, activityCursor, setActivityCursor, approvalCursor, setApprovalCursor, setModelEditor, setSuggestedRouterModel, refreshSerial, guard, selected, contextKey, questContextKey, writesBlocked, refreshConversation } = workspace;
  useEffect(() => {
    refreshSerial.current += 1;
    setRefreshing(false);
    setActionNotice("");
  }, [contextKey]);
  useEffect(() => {
    if (!actionNotice) return;
    const timeout = window.setTimeout(() => setActionNotice(""), 4500);
    return () => window.clearTimeout(timeout);
  }, [actionNotice]);
  const refreshPanel = useCallback(async () => {
    if (!connection || view === "chat" || view === "quests") return;
    const ticket = guard.start("panel");
    setPanelContext(contextKey);
    setPanel((old) => ({ ...old, loading: true, error: "" }));
    try {
      let value: unknown;
      if (view === "activity") value = await request(connection, `/api/activity?limit=100${selectedId ? `&quest_id=${encodeURIComponent(selectedId)}` : ""}`);
      else if (view === "models") value = await request(connection, "/api/models");
      else if (view === "memory") value = await request(connection, `/api/memory?limit=30&query=${encodeURIComponent(memorySearch)}`);
      else if (view === "settings") value = await Promise.all([request(connection, "/api/settings"), request(connection, "/api/budget")]);
      else if (!selectedId) value = [];
      else if (view === "teams") value = await request(connection, `/api/quests/${encodeURIComponent(selectedId)}/teams`);
      else value = await request(connection, `/api/approvals?quest_id=${encodeURIComponent(selectedId)}&limit=50`);
      if (!guard.accepts(ticket)) return;
      setPanel({ loading: false, error: "", value });
      if (view === "memory" && value && typeof value === "object") setMemoryCursor(text((value as Row).cursor, "") || null);
      if (view === "activity" && value && typeof value === "object") setActivityCursor(text((value as Row).next_before, "") || null);
      if (view === "approvals" && value && typeof value === "object") setApprovalCursor(text((value as Row).next_before, "") || null);
    } catch (error) { if (guard.accepts(ticket)) setPanel({ loading: false, error: errorMessage(error), value: null }); }
  }, [connection, view, selectedId, memorySearch, guard, contextKey]);

  useEffect(() => { setPanel(EMPTY); void refreshPanel(); }, [refreshPanel]);
  useEffect(() => {
    if (!connection || !selectedId || (view !== "quests" && view !== "teams")) { setQuestPlan(EMPTY); return; }
    let active = true;
    setPlanContext(questContextKey);
    setQuestPlan((previous) => ({ loading: true, error: "", value: planContext === questContextKey ? previous.value : null }));
    request<Row>(connection, `/api/quests/${encodeURIComponent(selectedId)}/plan`)
      .then((value) => { if (active) setQuestPlan({ loading: false, error: "", value }); })
      .catch((error) => { if (active) setQuestPlan({ loading: false, error: error instanceof ApiError && error.status === 404 ? "" : errorMessage(error), value: null }); });
    return () => { active = false; };
  }, [connection, selectedId, view, questContextKey, selected?.version, selected?.plan_revision, planRefresh]);

  const refreshGrants = useCallback(async () => {
    if (!connection || !selectedId || (view !== "quests" && view !== "approvals")) { setGrants(EMPTY); return; }
    const ticket = guard.start("grants");
    setGrantContext(`${questContextKey}|${view}`);
    setGrants({ loading: true, error: "", value: null });
    try {
      const [grantRows, settings] = await Promise.all([
        request<Row[]>(connection, `/api/quests/${encodeURIComponent(selectedId)}/grants`),
        request<Row>(connection, "/api/settings"),
      ]);
      if (!guard.accepts(ticket)) return;
      setGrants({ loading: false, error: "", value: grantRows });
      setWorkspaceRoot(text(settings.workspace_root, ""));
    } catch (error) { if (guard.accepts(ticket)) setGrants({ loading: false, error: errorMessage(error), value: null }); }
  }, [connection, selectedId, view, guard, questContextKey]);
  useEffect(() => { void refreshGrants(); }, [refreshGrants]);
  const refreshCurrentView = async () => {
    if (!connection || refreshing) return;
    const serial = ++refreshSerial.current;
    setRefreshing(true);
    setPlanRefresh((value) => value + 1);
    try { await Promise.all([refreshConversation(), refreshPanel(), refreshGrants()]); }
    finally { if (refreshSerial.current === serial) setRefreshing(false); }
  };
  useEffect(() => { setActionBusy(false); setActionError(""); }, [view, selectedId, connection?.generation]);
  useEffect(() => { setGrantScope(""); }, [selectedId]);
  useEffect(() => { setModelEditor(null); }, [view, connection?.generation]);
  useEffect(() => { setSuggestedRouterModel(null); }, [connection?.generation]);
  useEffect(() => {
    if (!connection || !selectedId || quests.some((quest) => quest.id === selectedId)) return;
    const ticket = guard.start("selected-quest");
    request<{quest: Quest}>(connection, `/api/quests/${encodeURIComponent(selectedId)}`)
      .then(({ quest }) => { if (guard.accepts(ticket)) setQuests((old) => old.some((item) => item.id === quest.id) ? old : [quest, ...old]); })
      .catch((error) => { if (guard.accepts(ticket)) setActionError(errorMessage(error)); });
  }, [connection, selectedId, quests, guard]);
  const loadPanelPage = async () => {
    if (!connection || panel.loading) return;
    const cursor = view === "memory" ? memoryCursor : view === "activity" ? activityCursor : view === "approvals" ? approvalCursor : null;
    if (!cursor) return;
    const ticket = guard.start("panel");
    setPanel((old) => ({ ...old, loading: true, error: "" }));
    try {
      const path = view === "memory"
        ? `/api/memory?limit=30&query=${encodeURIComponent(memorySearch)}&cursor=${encodeURIComponent(cursor)}`
        : view === "activity" ? `/api/activity?limit=100&before=${encodeURIComponent(cursor)}${selectedId ? `&quest_id=${encodeURIComponent(selectedId)}` : ""}`
        : `/api/approvals?quest_id=${encodeURIComponent(selectedId)}&limit=50&before=${encodeURIComponent(cursor)}`;
      const page = await request<Row>(connection, path);
      if (!guard.accepts(ticket)) return;
      setPanel((old) => {
        const current = old.value && typeof old.value === "object" ? old.value as Row : {};
        const existing = rows(current.items);
        const next = rows(page.items);
        const key = view === "activity" ? "run_id" : "id";
        const seen = new Set(existing.map((item) => item[key]));
        return { loading: false, error: "", value: { ...page, items: [...existing, ...next.filter((item) => !seen.has(item[key]))] } };
      });
      if (view === "memory") setMemoryCursor(text(page.cursor, "") || null);
      else if (view === "activity") setActivityCursor(text(page.next_before, "") || null);
      else setApprovalCursor(text(page.next_before, "") || null);
    } catch (error) { if (guard.accepts(ticket)) setPanel((old) => ({ ...old, loading: false, error: errorMessage(error) })); }
  };
  const perform = async (path: string, body?: unknown) => {
    if (!connection || actionBusy || writesBlocked || maintenanceSubmitting.current) return;
    const ticket = guard.start("action");
    setActionBusy(true); setActionError(""); setActionNotice("");
    try {
      await request(connection, path, { method: "POST", ...(body === undefined ? {} : { body: JSON.stringify(body) }) });
      if (!guard.accepts(ticket)) return;
      setActionNotice(path.includes("/decision") ? "审批决定已记录" : path.includes("/approvals/") && path.endsWith("/revoke") ? "审批已撤销" : path === "/api/approvals" ? "审批请求已创建" : path.includes("/plan/approve") ? "计划批准已记录" : path.includes("/teams/approve") ? "团队批准已记录" : path.includes("/grants") ? "工作区权限已更新" : path.includes("/memory/") ? "记忆已撤销" : path === "/api/settings" ? "运行配置已保存，重启 Core 后生效" : "更改已保存");
      await refreshConversation(); await refreshPanel();
      if (!guard.accepts(ticket)) return;
      if (path.includes("/grants")) await refreshGrants();
      if (selectedId && (view === "quests" || view === "teams")) {
        try {
          const value = await request<Row>(connection, `/api/quests/${encodeURIComponent(selectedId)}/plan`);
          if (guard.accepts(ticket)) setQuestPlan({ loading: false, error: "", value });
        } catch (error) {
          if (guard.accepts(ticket)) setQuestPlan({ loading: false, error: error instanceof ApiError && error.status === 404 ? "" : errorMessage(error), value: null });
        }
      }
    } catch (error) { if (guard.accepts(ticket)) setActionError(errorMessage(error)); }
    finally { if (guard.accepts(ticket)) setActionBusy(false); }
  };
  const openModel = async (id: string) => {
    if (!connection) return;
    const ticket = guard.start("model");
    setActionError("");
    try {
      const result = await request<{profile: Row; updated_at: string}>(connection, `/api/models/${encodeURIComponent(id)}`);
      if (guard.accepts(ticket)) setModelEditor({ initial: result.profile, version: result.updated_at });
    } catch (error) { if (guard.accepts(ticket)) setActionError(errorMessage(error)); }
  };

  const saveModel = async (method: "POST" | "PATCH", path: string, body: unknown) => {
    if (!connection || actionBusy || writesBlocked || maintenanceSubmitting.current) return;
    const ticket = guard.start("model");
    setActionBusy(true); setActionError("");
    try {
      await request(connection, path, { method, body: JSON.stringify(body) });
      if (!guard.accepts(ticket)) return;
      setModelEditor(null);
      await refreshPanel();
    } catch (error) { if (guard.accepts(ticket)) setActionError(errorMessage(error)); }
    finally { if (guard.accepts(ticket)) setActionBusy(false); }
  };
  return { refreshPanel, refreshGrants, refreshCurrentView, loadPanelPage, perform, openModel, saveModel };
}

import { useEffect, useId, useRef, useState, type FormEvent } from "react";
import { type Connection } from "../../api";
import { errorMessage } from "../../logic";
import { SettingsSection } from "../../SettingsView";
import { asRecord, rows, text, type Row } from "../../workspaceTypes";
import { eventPayload, fileWatchInput, scheduleInput, sourceInput, triggerInput, type AdmissionMode, type PayloadFormat } from "./settingsInputs";
import useSettingsRequests from "./useSettingsRequests";

type Operation = "source" | "event" | "schedule" | "watch";
const sourceKinds: Record<string, string> = { external: "外部事件", timer: "定时任务", file: "文件监听" };
const admissionModes: Record<AdmissionMode, string> = { candidate: "交给 Router 判断", explicit: "仅接收明确发给助手的事件", ignore: "忽略此源" };
const triggerStates: Record<string, string> = { pending: "等待 Router 处理", filtered: "已过滤", passed_through: "已交给订阅成员", routed: "已路由", completed: "已处理" };

function ContentInput({ label, value, onChange, format, onFormat }: { label: string; value: string; onChange: (value: string) => void; format: PayloadFormat; onFormat: (value: PayloadFormat) => void }) {
  return <><label className="field-label">内容格式<select value={format} onChange={(event) => onFormat(event.target.value as PayloadFormat)}><option value="text">文本</option><option value="json">结构化内容（JSON 对象）</option></select></label>
    <label className="field-label">{label}<textarea rows={3} required value={value} onChange={(event) => onChange(event.target.value)} placeholder={format === "json" ? '{"content":"需要处理的内容"}' : "描述需要处理的事件"} /></label></>;
}

function TriggerRecord({ item }: { item: Row }) {
  let preview = text(item.preview, "");
  try { const payload = asRecord(JSON.parse(preview)); if (typeof payload.content === "string") preview = payload.content; } catch { /* A bounded preview may end in the middle of JSON. */ }
  return <div className="settings-result-record"><strong>{text(item.thread_key, text(item.id))}</strong><small>{text(item.source_id)} · {triggerStates[text(item.status)] || text(item.status)}</small>
    {preview && <p>{preview}</p>}<details className="settings-disclosure"><summary>事件记录</summary><dl><dt>事件标识</dt><dd className="break">{text(item.external_id)}</dd><dt>记录 ID</dt><dd className="break">{text(item.id)}</dd><dt>路由原因</dt><dd>{text(item.reason)}</dd><dt>重复接收</dt><dd>{item.duplicate === true ? "是" : "否"}</dd></dl></details></div>;
}

export default function TriggersSettings(props: { connection: Connection | null; blocked: boolean }) {
  const identity = props.connection ? `${props.connection.base_url}|${props.connection.workspace_id || ""}|${props.connection.generation}` : "disconnected";
  return <TriggerControls key={identity} {...props} />;
}

function TriggerControls({ connection, blocked }: { connection: Connection | null; blocked: boolean }) {
  const { run } = useSettingsRequests();
  const [pending, setPending] = useState<Row[]>([]);
  const [loading, setLoading] = useState(false);
  const [loadError, setLoadError] = useState("");
  const [refresh, setRefresh] = useState(0);
  const [busy, setBusy] = useState<Operation | null>(null);
  const mutationPending = useRef(false);
  const [error, setError] = useState<{ operation: Operation; message: string } | null>(null);
  const [notice, setNotice] = useState<{ operation: Operation; message: string } | null>(null);
  const [sources, setSources] = useState<Row[]>([]);
  const [source, setSource] = useState("");
  const [kind, setKind] = useState("external");
  const [mode, setMode] = useState<AdmissionMode>("candidate");
  const [actors, setActors] = useState("");
  const [eventSource, setEventSource] = useState("");
  const [externalId, setExternalId] = useState(() => `event_${crypto.randomUUID()}`);
  const [thread, setThread] = useState("");
  const [actor, setActor] = useState("");
  const [addressed, setAddressed] = useState(false);
  const [content, setContent] = useState("");
  const [format, setFormat] = useState<PayloadFormat>("text");
  const [eventReceipt, setEventReceipt] = useState<Row | null>(null);
  const [timerSource, setTimerSource] = useState("");
  const [timerThread, setTimerThread] = useState("");
  const [timerContent, setTimerContent] = useState("");
  const [timerFormat, setTimerFormat] = useState<PayloadFormat>("text");
  const [dueAt, setDueAt] = useState("");
  const [interval, setInterval] = useState("");
  const [timerReceipt, setTimerReceipt] = useState<Row | null>(null);
  const [fileSource, setFileSource] = useState("");
  const [filePath, setFilePath] = useState("");
  const [fileThread, setFileThread] = useState("");
  const [watchReceipt, setWatchReceipt] = useState<Row | null>(null);
  const sourceList = useId();
  const disabled = !connection || blocked || busy !== null;

  useEffect(() => {
    if (!connection) return;
    setLoading(true); setLoadError("");
    void run<Row[]>("pending", connection, "/api/triggers?limit=32").then((result) => {
      if (result) { setPending(rows(result.value)); setLoading(false); }
    }).catch((problem) => { setLoadError(errorMessage(problem)); setLoading(false); });
  }, [connection, refresh, run]);

  const submit = async (event: FormEvent, operation: Operation, path: string, makePayload: () => unknown, success: (value: Row) => void) => {
    event.preventDefault();
    if (!connection || blocked || mutationPending.current) return;
    setError(null); setNotice(null);
    let payload: unknown;
    try { payload = makePayload(); } catch (problem) { setError({ operation, message: errorMessage(problem) }); return; }
    mutationPending.current = true; setBusy(operation);
    try {
      const result = await run<Row>("mutation", connection, path, { method: "POST", body: JSON.stringify(payload) });
      if (result) { success(result.value); setRefresh((value) => value + 1); setBusy(null); }
    } catch (problem) { setError({ operation, message: errorMessage(problem) }); setBusy(null); }
    finally { mutationPending.current = false; }
  };
  const feedback = (operation: Operation) => <>{error?.operation === operation && <p className="notice error" role="alert">{error.message} 表单已保留，请核对后重试。</p>}{notice?.operation === operation && <p className="notice" role="status">{notice.message}</p>}</>;

  return <div className="settings-blocks trigger-settings">
    {!connection && <p className="notice">连接 Core 后可管理事件触发器。</p>}
    <SettingsSection title="待处理事件" description="显示最早的 32 条待处理事件；处理后会从此列表移除。">
      <div className="settings-form-content"><button className="button" type="button" disabled={!connection || loading} onClick={() => setRefresh((value) => value + 1)}>{loading ? "正在刷新…" : "刷新待处理事件"}</button>{loadError && <p className="notice error" role="alert">{loadError}</p>}{!loading && !loadError && !pending.length && <p className="notice">暂无待处理事件</p>}</div>
      {pending.map((item, index) => <TriggerRecord key={text(item.id, String(index))} item={item} />)}
    </SettingsSection>
    <SettingsSection title="事件源" description="先注册事件源，再接收事件、创建定时任务或文件监听。同一标识的类型与接收规则须保持一致。">
      <form className="settings-inline-form" onSubmit={(event) => void submit(event, "source", "/api/triggers/sources", () => sourceInput(source, kind, mode, actors), (value) => {
        setSources((current) => [...current.filter((item) => item.id !== value.id), value]);
        if (!eventSource) setEventSource(source.trim());
        if (kind === "timer") setTimerSource(source.trim());
        if (kind === "file") setFileSource(source.trim());
        setNotice({ operation: "source", message: `已注册事件源 ${text(value.id, source.trim())}` });
      })}>
        <label className="field-label">事件源标识<input value={source} required maxLength={256} onChange={(event) => setSource(event.target.value)} placeholder="例如 build-events" /></label>
        <label className="field-label">事件源类型<select value={kind} onChange={(event) => setKind(event.target.value)}>{Object.entries(sourceKinds).map(([id, label]) => <option key={id} value={id}>{label}</option>)}</select></label>
        <label className="field-label">接收规则<select value={mode} onChange={(event) => setMode(event.target.value as AdmissionMode)}>{Object.entries(admissionModes).map(([id, label]) => <option key={id} value={id}>{label}</option>)}</select></label>
        <label className="field-label">允许的来源用户<textarea rows={2} value={actors} onChange={(event) => setActors(event.target.value)} placeholder="每行一个标识；留空不限制来源用户" /></label>
        <div className="settings-form-content"><button type="submit" className="button" disabled={disabled}>{busy === "source" ? "正在注册…" : "注册事件源"}</button>{feedback("source")}</div>
      </form>
      {sources.length > 0 && <div className="settings-form-content"><p className="notice">本次打开设置后注册的事件源</p>{sources.map((item) => <div className="settings-result-record" key={text(item.id)}><strong>{text(item.id)}</strong><small>{sourceKinds[text(item.kind)] || text(item.kind)} · {admissionModes[text(item.mode) as AdmissionMode] || text(item.mode)}</small></div>)}</div>}
    </SettingsSection>
    <datalist id={sourceList}>{sources.map((item) => <option key={text(item.id)} value={text(item.id)}>{sourceKinds[text(item.kind)] || text(item.kind)}</option>)}</datalist>
    <SettingsSection title="接收事件" description="把外部事件交给已注册的事件源。相同事件标识可去重；失败时保留标识和内容。">
      <form className="settings-inline-form" onSubmit={(event) => void submit(event, "event", "/api/triggers", () => triggerInput(eventSource, externalId, thread, content, format, actor, addressed), (value) => { setEventReceipt(value); setNotice({ operation: "event", message: `事件已接收 · ${triggerStates[text(value.status)] || text(value.status)}` }); })}>
        <label className="field-label">事件源标识<input required list={sourceList} maxLength={256} value={eventSource} onChange={(event) => setEventSource(event.target.value)} /></label>
        <label className="field-label">主题标识<input required maxLength={256} value={thread} onChange={(event) => setThread(event.target.value)} placeholder="同一话题使用相同标识" /></label>
        <ContentInput label="事件内容" value={content} onChange={setContent} format={format} onFormat={setFormat} />
        <details className="settings-disclosure settings-form-content"><summary>事件来源与去重</summary><div className="settings-disclosure-body"><label className="field-label">事件标识<input required maxLength={256} value={externalId} onChange={(event) => setExternalId(event.target.value)} /></label><label className="field-label">来源用户<input value={actor} maxLength={256} onChange={(event) => setActor(event.target.value)} /></label><label className="check-label"><input type="checkbox" checked={addressed} onChange={(event) => setAddressed(event.target.checked)} />此事件明确发给助手</label><button type="button" className="text-button" disabled={disabled} onClick={() => { setExternalId(`event_${crypto.randomUUID()}`); setEventReceipt(null); }}>生成新的事件标识</button></div></details>
        <div className="settings-form-content"><button className="button" type="submit" disabled={disabled}>{busy === "event" ? "正在接收…" : "接收此事件"}</button>{feedback("event")}</div>
      </form>{eventReceipt && <TriggerRecord item={eventReceipt} />}
    </SettingsSection>
    <SettingsSection title="定时任务" description="使用定时类型的事件源。执行时生成事件，再由 Router 或订阅成员处理。">
      <form className="settings-inline-form" onSubmit={(event) => void submit(event, "schedule", "/api/triggers/schedules", () => scheduleInput(timerSource, timerThread, timerContent, timerFormat, dueAt, interval), (value) => { setTimerReceipt(value); setNotice({ operation: "schedule", message: "定时任务已创建" }); })}>
        <label className="field-label">定时事件源<input required list={sourceList} maxLength={256} value={timerSource} onChange={(event) => setTimerSource(event.target.value)} /></label>
        <label className="field-label">定时主题标识<input required maxLength={256} value={timerThread} onChange={(event) => setTimerThread(event.target.value)} /></label>
        <ContentInput label="定时任务内容" value={timerContent} onChange={setTimerContent} format={timerFormat} onFormat={setTimerFormat} />
        <label className="field-label">执行时间（本地）<input type="datetime-local" required value={dueAt} onChange={(event) => setDueAt(event.target.value)} /></label>
        <label className="field-label">重复间隔（秒）<input type="number" min="1" step="any" value={interval} onChange={(event) => setInterval(event.target.value)} placeholder="留空只执行一次" /></label>
        <div className="settings-form-content"><button className="button" type="submit" disabled={disabled}>{busy === "schedule" ? "正在创建…" : "创建定时任务"}</button>{feedback("schedule")}</div>
      </form>{timerReceipt && <div className="settings-result-record"><strong>本次创建的定时任务</strong><small className="break">{text(timerReceipt.id)}</small><dl><dt>下次执行</dt><dd>{typeof timerReceipt.next_at === "number" ? new Date(timerReceipt.next_at * 1000).toLocaleString() : "未记录"}</dd><dt>重复间隔</dt><dd>{typeof timerReceipt.interval_seconds === "number" ? `${timerReceipt.interval_seconds} 秒` : "仅执行一次"}</dd></dl></div>}
    </SettingsSection>
    <SettingsSection title="文件监听" description="使用文件类型的事件源，监听工作空间内的普通文件。文件变化会生成事件。">
      <form className="settings-inline-form" onSubmit={(event) => void submit(event, "watch", "/api/triggers/file-watches", () => fileWatchInput(fileSource, filePath, fileThread), (value) => { setWatchReceipt(value); setNotice({ operation: "watch", message: "文件监听已创建" }); })}>
        <label className="field-label">文件事件源<input required list={sourceList} maxLength={256} value={fileSource} onChange={(event) => setFileSource(event.target.value)} /></label>
        <label className="field-label">相对文件路径<input required value={filePath} onChange={(event) => setFilePath(event.target.value)} placeholder="例如 reports/latest.txt" /></label>
        <label className="field-label">文件主题标识<input maxLength={256} value={fileThread} onChange={(event) => setFileThread(event.target.value)} placeholder="留空使用文件路径" /></label>
        <div className="settings-form-content"><button className="button" type="submit" disabled={disabled}>{busy === "watch" ? "正在创建…" : "创建文件监听"}</button>{feedback("watch")}</div>
      </form>{watchReceipt && <div className="settings-result-record"><strong className="break">{text(watchReceipt.relative_path)}</strong><small className="break">本次创建的监听 · {text(watchReceipt.id)}</small><small>主题：{text(watchReceipt.thread_key)}</small></div>}
    </SettingsSection>
  </div>;
}

import { useEffect, useRef, useState } from "react";
import type { Connection } from "../../api";
import { errorMessage } from "../../logic";
import { capabilityLabel } from "../../presentation";
import { SettingsSection } from "../../SettingsView";
import { asRecord, rows, text, type Row } from "../../workspaceTypes";
import { modelProbeInput, PROBE_DIMENSIONS } from "./settingsInputs";
import useSettingsRequests from "./useSettingsRequests";

export interface ModelIntelligenceProps {
  connection: Connection | null;
  models: Row[];
  blocked: boolean;
  onModelsChanged: () => void;
}

const metricLabels: Record<string, string> = {
  transport_success_rate: "请求传输成功率", transport_error_rate: "请求错误率", transport_timeout_rate: "请求超时率",
  task_success_rate: "任务成功率", worker_blocked_rate: "执行阻塞率", tool_call_success_rate: "工具调用成功率",
  review_pass_rate: "节点验证通过率", independent_review_verdict_pass_rate: "独立复核通过率", independent_review_error_rate: "独立复核错误率",
  schema_compliance: "输出结构符合率", retry_rate: "重试比例", retry_count: "重试次数", token_consumption: "已确认 Token 消耗",
  average_latency_seconds: "平均延迟", p95_latency_seconds: "P95 延迟", tokens_per_second: "输出速度", cost_microunits: "已确认费用",
};
const healthLabels: Record<string, string> = { available: "近期传输可用", degraded: "近期传输异常", blocked_unknown: "存在未确认的调用", unknown: "尚无健康观测" };
const finite = (value: unknown): value is number => typeof value === "number" && Number.isFinite(value);
const percent = (value: number) => `${(value * 100).toLocaleString(undefined, { maximumFractionDigits: 1 })}%`;
const observedAt = (value: unknown) => typeof value === "string" && Number.isFinite(Date.parse(value)) ? new Date(value).toLocaleString() : "未记录";

function measurementValue(name: string, entry: Row): string {
  if (!finite(entry.value)) return "未知";
  if (name.endsWith("_rate") || name === "schema_compliance" || (PROBE_DIMENSIONS as readonly string[]).includes(name)) return percent(entry.value);
  const number = entry.value.toLocaleString(undefined, { maximumFractionDigits: 2 });
  if (name.endsWith("_seconds")) return `${number} 秒`;
  if (name === "tokens_per_second") return `${number} Token/s`;
  if (name === "cost_microunits") return `${(entry.value / 1000000).toLocaleString(undefined, { maximumFractionDigits: 6 })} ${text(entry.currency, "币种未知")}`;
  return number;
}

function Measurement({ name, value }: { name: string; value: unknown }) {
  const entry = asRecord(value);
  const confidence = asRecord(entry.confidence);
  const interval = finite(confidence.lower) && finite(confidence.upper) ? `${percent(confidence.lower)} – ${percent(confidence.upper)}` : null;
  return <div className="model-measurement"><span>{metricLabels[name] || capabilityLabel(name)}</span><div><strong>{measurementValue(name, entry)}</strong><small>{finite(entry.n_samples) ? `${entry.n_samples} 个样本` : "样本未知"}{interval && ` · 95% 区间 ${interval}`}</small></div></div>;
}

function Snapshot({ value }: { value: Row }) {
  const health = asRecord(value.health), performance = asRecord(value.performance), capabilities = asRecord(value.capabilities);
  const measurements = asRecord(performance.measurements), scores = asRecord(capabilities.measurements);
  const healthKnown = text(health.recommendation, "unknown");
  const references = [...new Set([performance, health, capabilities].flatMap((section) => Array.isArray(section.source_refs) ? section.source_refs.filter((value): value is string => typeof value === "string") : []))];
  return <div className="model-observations">
    <div className="settings-result-record"><strong>{healthLabels[healthKnown] || healthKnown}</strong><small>未确认调用 {text(health.unknown_attempts)} · 执行中 {text(health.in_flight_calls)} · 连续失败 {text(health.consecutive_failures)}</small><small>最近观测：{observedAt(health.observed_at)}</small></div>
    <div className="settings-form-content"><h3 className="settings-block-heading">实际运行观测</h3><p className="notice">以下仅描述已记录的执行；传输成功与任务成功分别统计。</p>{Object.keys(measurements).length ? Object.entries(measurements).map(([name, entry]) => <Measurement key={name} name={name} value={entry} />) : <p className="notice">暂无实际运行样本</p>}{finite(performance.unknown_usage_attempts) && performance.unknown_usage_attempts > 0 && <p className="notice">另有 {performance.unknown_usage_attempts} 次调用的用量尚未确认。</p>}</div>
    <div className="settings-form-content"><h3 className="settings-block-heading">固定样例测量</h3><p className="notice">每个维度为固定的公开小样例，不代表总体能力。视觉未受此文字基准支持。</p>{PROBE_DIMENSIONS.map((name) => <Measurement key={name} name={name} value={scores[name]} />)}<p className="notice">测量时间：{observedAt(capabilities.measured_at)} · 基准：{text(capabilities.suite_version)}</p></div>
    {references.length > 0 && <details className="settings-disclosure settings-form-content"><summary>观测来源（{references.length} 条）</summary><div className="settings-disclosure-body"><ul className="model-source-refs">{references.map((reference) => <li key={reference}>{reference}</li>)}</ul>{finite(performance.source_refs_omitted) && performance.source_refs_omitted > 0 && <p className="notice">另有 {performance.source_refs_omitted} 条执行来源未在本次响应中展开。</p>}</div></details>}
  </div>;
}

export default function ModelIntelligence(props: ModelIntelligenceProps) {
  const identity = props.connection ? `${props.connection.base_url}|${props.connection.workspace_id || ""}|${props.connection.generation}` : "disconnected";
  return <ModelControls key={identity} {...props} />;
}

function ModelControls({ connection, models, blocked, onModelsChanged }: ModelIntelligenceProps) {
  const { run, cancel } = useSettingsRequests();
  const [profileId, setProfileId] = useState(() => typeof models[0]?.id === "string" ? models[0].id : "");
  const [dimensions, setDimensions] = useState<string[]>(["mathematics"]);
  const [busy, setBusy] = useState<"discover" | "benchmark" | null>(null);
  const mutationPending = useRef(false);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [loading, setLoading] = useState(false);
  const [loadError, setLoadError] = useState("");
  const [reload, setReload] = useState(0);
  const [snapshot, setSnapshot] = useState<{ profileId: string; value: Row } | null>(null);
  const [report, setReport] = useState<{ profileId: string; value: Row } | null>(null);
  const selected = models.find((model) => model.id === profileId);
  const canBenchmark = !!connection && !blocked && !busy && selected?.enabled === true && !selected.quarantine_reason && dimensions.length > 0;

  useEffect(() => {
    if (!models.some((model) => model.id === profileId)) setProfileId(typeof models[0]?.id === "string" ? models[0].id : "");
  }, [models, profileId]);

  useEffect(() => {
    setLoadError("");
    if (!connection || !profileId) { setLoading(false); return; }
    setLoading(true);
    void run<Row>("snapshot", connection, `/api/model-intelligence/${encodeURIComponent(profileId)}`).then((result) => {
      if (result) { setSnapshot({ profileId, value: result.value }); setLoading(false); }
    }).catch((problem) => { setLoadError(errorMessage(problem)); setLoading(false); });
    return () => cancel("snapshot");
  }, [connection, profileId, reload, run, cancel]);

  const mutate = async (operation: "discover" | "benchmark") => {
    if (!connection || blocked || mutationPending.current || operation === "benchmark" && !canBenchmark) return;
    setError(""); setNotice("");
    let init: RequestInit = { method: "POST" };
    try { if (operation === "benchmark") init = { ...init, body: JSON.stringify(modelProbeInput(profileId, dimensions)) }; }
    catch (problem) { setError(errorMessage(problem)); return; }
    mutationPending.current = true; setBusy(operation);
    try {
      const result = await run<unknown>("mutation", connection, `/api/model-intelligence/${operation}`, init);
      if (result) {
        if (operation === "discover") {
          const added = rows(result.value);
          setNotice(added.length ? `已发现 ${added.length} 个新模型，模型库已刷新。` : "未发现新的模型档案。");
          onModelsChanged();
        } else {
          const value = asRecord(result.value);
          setReport({ profileId, value }); setReload((current) => current + 1);
          setNotice("固定样例测量已记录。请查看各维度结果。");
        }
        setBusy(null);
      }
    } catch (problem) { setError(errorMessage(problem)); setBusy(null); }
    finally { mutationPending.current = false; }
  };

  return <div className="settings-blocks model-intelligence">
    <SettingsSection title="模型发现与测量" description="从已配置的供应商发现模型，查看实际运行观测与固定样例结果。">
      <div className="settings-form-content"><button type="button" className="button" disabled={!connection || blocked || busy !== null} onClick={() => void mutate("discover")}>{busy === "discover" ? "正在发现…" : "从供应商发现模型"}</button>{!connection && <p className="notice">连接 Core 后可读取和测量模型。</p>}</div>
      <label className="field-label">观测模型<select value={profileId} disabled={!models.length || busy !== null} onChange={(event) => { setProfileId(event.target.value); setError(""); setNotice(""); }}><option value="">选择模型档案</option>{models.filter((model) => typeof model.id === "string").map((model) => <option key={text(model.id)} value={text(model.id)}>{text(model.display_name, text(model.model_id, text(model.id)))} · {text(model.provider)}</option>)}</select></label>
      <div className="settings-form-content"><button className="text-button" type="button" disabled={!connection || !profileId || loading} onClick={() => setReload((current) => current + 1)}>{loading ? "正在读取观测…" : "刷新模型观测"}</button>{loadError && <p className="notice error" role="alert">{loadError}</p>}</div>
      {snapshot?.profileId === profileId && <Snapshot value={snapshot.value} />}
    </SettingsSection>
    <SettingsSection title="运行固定样例" description="点击开始后会真实调用所选模型并消耗预算；每个已选维度至多调用一次，失败不会自动重试。">
      <fieldset className="model-probe-dimensions" disabled={!connection || blocked || busy !== null}><legend>测量维度</legend>{PROBE_DIMENSIONS.filter((dimension) => dimension !== "vision").map((dimension) => <label key={dimension}><input type="checkbox" checked={dimensions.includes(dimension)} onChange={(event) => setDimensions((current) => event.target.checked ? [...current, dimension] : current.filter((item) => item !== dimension))} />{capabilityLabel(dimension)}</label>)}<span className="notice">视觉：当前基准不支持</span></fieldset>
      <div className="settings-form-content">{selected && selected.enabled !== true && <p className="notice">此模型尚未启用，请先在模型档案中启用。</p>}{selected?.quarantine_reason != null && selected.quarantine_reason !== "" && <p className="notice">此模型档案已隔离，暂不能运行测量。</p>}<button className="button" type="button" disabled={!canBenchmark} onClick={() => void mutate("benchmark")}>{busy === "benchmark" ? "正在运行样例…" : "开始固定样例测量"}</button>{busy === "benchmark" && <p className="notice" role="status">等待模型返回。本次测量结果将保留在所选模型的观测中。</p>}{error && <p className="notice error" role="alert">{error} 本次请求未自动重试。</p>}{notice && <p className="notice" role="status">{notice}</p>}</div>
