    : [active ? `${active} 运行中` : "", done ? `${done} 完成` : "", failed ? `${failed} 失败` : "", !active && !done && !failed && runs.length ? `${runs.length} 条记录` : ""].filter(Boolean).join(" · ") || "暂无运行";
